statement:
You get an integer array `banned` and two integers `n` and `maxSum`. Pick a collection of integers that obeys all of these rules:

- every picked integer lies between `1` and `n` inclusive;
- no integer is picked more than once;
- no picked integer occurs in `banned` (values in `banned` may repeat);
- the picked integers add up to no more than `maxSum`.

Return the largest number of integers such a collection can contain (`0` if nothing can be picked).

validator:
function validate([banned, n, maxSum]) {
  if (!Number.isInteger(n) || n < 1 || n > 1000000000) return 'n is between 1 and 10^9.';
  if (!Array.isArray(banned) || banned.length < 1 || banned.length > 100000) return 'banned needs 1 to 10^5 values.';
  if (banned.some(v => !Number.isInteger(v) || v < 1 || v > n)) return 'Each banned value is an integer from 1 to n.';
  if (!Number.isInteger(maxSum) || maxSum < 1 || maxSum > 1000000000000000) return 'maxSum is between 1 and 10^15.';
  return null;
}

reference:
function maxCount(banned, n, maxSum) {
  const blocked = [...new Set(banned)].sort((a, b) => a - b);
  const prefix = [0];
  for (const value of blocked) {
    prefix.push(prefix[prefix.length - 1] + value);
  }

  const blockedUpTo = (limit) => {
    let low = 0;
    let high = blocked.length;
    while (low < high) {
      const middle = (low + high) >> 1;
      if (blocked[middle] <= limit) {
        low = middle + 1;
      } else {
        high = middle;
      }
    }
    return low;
  };
  const costUpTo = (limit) => limit * (limit + 1) / 2 - prefix[blockedUpTo(limit)];

  let left = 0;
  let right = n;
  while (left < right) {
    const mid = left + Math.ceil((right - left) / 2);
    if (costUpTo(mid) <= maxSum) {
      left = mid;
    } else {
      right = mid - 1;
    }
  }
  return left - blockedUpTo(left);
}

brute:
function maxCount(banned, n, maxSum) {
  // Take the allowed integers from smallest to largest until the next one no longer fits.
  const skip = new Set(banned);
  let total = 0, count = 0;
  for (let value = 1; value <= n; value++) {
    if (skip.has(value)) continue;
    if (total + value > maxSum) break;
    total += value;
    count++;
  }
  return count;
}

