function generate(rand, size) {
  if (size === 'large') {
    const n = 1 + Math.floor(rand() * 1000000000);
    const maxSum = 1 + Math.floor(rand() * 1000000000000000);
    // Most banned values fall below the point where the budget runs out, so they matter.
    const reach = Math.min(n, Math.ceil(Math.sqrt(2 * maxSum)) + 3000);
    const banned = Array.from({ length: 2000 }, () => 1 + Math.floor(rand() * (rand() < 0.8 ? reach : n)));
    return [banned, n, maxSum];
  }
  const n = 1 + Math.floor(rand() * 15);
  const banned = Array.from({ length: 1 + Math.floor(rand() * 6) }, () => 1 + Math.floor(rand() * n));
  const maxSum = 1 + Math.floor(rand() * (n * (n + 1) / 2 + 5));
  return [banned, n, maxSum];
}
